titles.hosts='连接与设备';titles.tools='调试工具';
const oldSave=save;save=function(){oldSave();try{const value=JSON.parse(localStorage.getItem('termpilot-prototype-v2')||'{}');value.embeddedVersion=1;localStorage.setItem('termpilot-prototype-v2',JSON.stringify(value))}catch{}};
const addrLabel=h=>h.kind==='串口'?`${h.device||h.addr} · ${h.baud||115200} ${h.dataBits||8}${h.parity==='Even'?'E':h.parity==='Odd'?'O':'N'}${h.stopBits||1}`:h.kind==='本地终端'?'本机 Shell · 模拟':h.kind==='ADB'?h.serial||h.addr:`${h.user?h.user+'@':''}${h.addr}${h.port?':'+h.port:''}`;
const oldShell=shell;shell=function(){oldShell();const navSection=document.querySelector('.sidebar nav.nav-section');if(navSection)navSection.insertAdjacentHTML('beforeend',nav('调试工具','tools','terminal'));const mobile=document.querySelector('.mobile-nav');if(mobile)mobile.insertAdjacentHTML('beforeend',nav('工具','tools','terminal'));};
const oldRenderView=renderView;renderView=function(){if(state.page==='tools'){document.getElementById('view').innerHTML=toolsView();document.title='调试工具 · TermPilot'}else oldRenderView()};
visibleHosts=function(){return state.hosts.filter(h=>(state.group==='ALL'||h.group===state.group)&&(state.kindFilter==='ALL'||h.kind===state.kindFilter)&&[h.name,addrLabel(h),h.group,h.kind].join(' ').toLowerCase().includes(state.query.toLowerCase()))};
hostRows=function(){const rows=visibleHosts();return rows.length?`<div class="table-heading"><span>设备 / 连接地址</span><span class="host-env">连接方式</span><span>会话状态</span><span></span></div>${rows.map(h=>`<div class="host-item ${state.selected===h.id?'selected':''}"><button class="host-name" data-host="${esc(h.id)}" aria-pressed="${state.selected===h.id}"><span class="host-glyph">${icon(h.kind==='串口'?'serial':h.kind==='本地终端'?'terminal':'server')}</span><span class="od-field od-fill"><strong class="od-truncate">${esc(h.name)}</strong><small class="od-truncate">${esc(addrLabel(h))}</small></span></button><span class="tag host-env">${esc(h.kind)}</span><span class="tag ${state.sessions.includes(h.id)&&!state.disconnected.has(h.id)?'connected':''}">${state.disconnected.has(h.id)?'已断开':state.sessions.includes(h.id)?'已连接':'未连接'}</span>${ib('连接 '+esc(h.name),'connect:'+esc(h.id),'arrow')}</div>`).join('')}`:`<div class="empty">${icon('search')}<h3>没有匹配的连接</h3><p>可清除筛选，或新建网络与串口连接。</p>${btn('清除筛选','emb:clear')}</div>`};
detailView=function(){if(!state.hosts.length)return '<div class="empty"><p>新建连接以开始。</p></div>';const h=host();const facts=h.kind==='串口'?[['串口设备',h.device||h.addr],['串口参数',`${h.baud||115200} baud · ${h.dataBits||8} data · ${h.parity||'None'} · ${h.stopBits||1} stop`],['流控 / 编码',`${h.flow||'None'} / ${h.encoding||'UTF-8'}`],['发送行尾',h.lineEnding||'CRLF']]:h.kind==='本地终端'?[['Shell',h.shell||'系统默认'],['工作目录',h.cwd||'用户目录']]:h.kind==='ADB'?[['设备序列号',h.serial||h.addr],['状态','示例设备 · 未访问 ADB']]:[['地址',h.addr],['端口',h.port],...(h.user?[['用户',h.user]]:[]),...(['SSH','Mosh'].includes(h.kind)?[['认证',h.auth||'SSH Agent'],['主机键校验',h.verify||'接受新主机（TOFU）']]:[])];return `<div class="detail-top"><div class="host-glyph">${icon(h.kind==='串口'?'serial':'server')}</div><div class="od-field"><h2>${esc(h.name)}</h2><span class="tag">${esc(h.kind)} · ${esc(h.group)}</span></div>${btn(h.kind==='串口'?'打开串口':'连接设备','connect:'+esc(h.id),'primary wide','terminal')}</div><div class="detail-section"><dl>${facts.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="detail-note">${h.kind==='串口'?'串口参数按连接独立保存。设备列表与收发均为模拟。':['Telnet','TCP'].includes(h.kind)?'此连接无传输加密，请在可信网络使用。当前仅为演示。':'连接与服务结果均为演示，不访问真实设备。'}</p><div class="button-row">${btn('编辑','edit-host','','edit')}${btn('删除','delete-host','quiet danger','trash')}</div></div>`};
hostsView=function(){return `<div class="page">${pageHead('连接与设备','从开发板启动日志，到远程 Linux，会话集中在这里。',btn('快速连接','quick','','terminal')+btn('新建连接','new-host','primary','plus'),'EMBEDDED WORKSPACE')}<div class="workflow-strip"><div class="od-field"><strong>${icon('serial')}串口调试</strong><span>UART · 启动日志 · HEX 收发</span></div><div class="od-field"><strong>${icon('terminal')}网络终端</strong><span>SSH · Telnet · TCP · ADB</span></div><div class="od-field"><strong>${icon('folder')}文件与工具</strong><span>SFTP · Bootloader 传输 · GDB</span></div></div><div class="toolbar"><label class="searchbox">${icon('search')}<span class="hidden-label">搜索连接</span><input id="hostSearch" type="search" placeholder="搜索名称、设备路径或地址" value="${esc(state.query)}"></label><span class="grow"></span><label class="filter-select"><span>类型</span><select id="kindFilter"><option value="ALL">全部类型</option>${kinds.map(v=>`<option ${state.kindFilter===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="host-layout"><section><div class="list-heading"><h2>保存的连接</h2><span class="count" id="hostCount">${visibleHosts().length} 项</span></div><div class="host-table" id="hostRows">${hostRows()}</div><div class="host-bottom"><span>网络主机与串口设备使用各自的配置</span><span>所有设备均为示例</span></div><div class="button-row result-block">${btn('串口快速开始','emb:serial-new','','serial')}${btn('调试工具','emb:tools','','terminal')}${btn('能力覆盖','emb:coverage','','shield')}</div></section><aside class="detail" id="hostDetail">${detailView()}</aside></div></div>`};
